  "commands": [
    {
      "keystrokes": "python3 ./yt-dlp -F 'https://www.youtube.com/watch?v=ZCbvyPbhRfA' --extractor-args \"youtube:player_client=ios\" 2>&1 | tail -30\n",
      "duration": 20
    }
  ]
}

